CREATE FUNCTION public.influencer_services_touch() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE l record; BEGIN IF TG_TABLE_NAME='custom_plan_services' THEN FOR l IN SELECT id FROM client_launches WHERE custom_plan_id=NEW.custom_plan_id AND status IN('draft','awaiting_day0','active','live') LOOP PERFORM ensure_influencer_program(l.id); END LOOP; ELSE FOR l IN SELECT id FROM client_launches WHERE custom_plan_id IS NULL AND plan_version_id=NEW.plan_version_id AND status IN('draft','awaiting_day0','active','live') LOOP PERFORM ensure_influencer_program(l.id); END LOOP; END IF; RETURN NEW; END $$; CREATE TRIGGER influencer_services_touch AFTER INSERT OR UPDATE ON public.plan_services FOR EACH ROW EXECUTE FUNCTION public.influencer_services_touch(); CREATE TRIGGER influencer_custom_services_touch AFTER INSERT OR UPDATE ON public.custom_plan_services FOR EACH ROW EXECUTE FUNCTION public.influencer_services_touch();